/* Optional static effects. */
@layer syn.effects {
  /* All component rules match the root itself or a descendant, never a host sibling. */
  :where(.syn-root, .syn-root *) {
    &.syn-grid-effect {
      background-image:
        linear-gradient(to right, color-mix(in srgb, var(--syn-accent) var(--syn-grid-alpha, 5%), transparent) 1px, transparent 1px),
        linear-gradient(to bottom, color-mix(in srgb, var(--syn-accent) var(--syn-grid-alpha, 5%), transparent) 1px, transparent 1px);
      background-size: 2rem 2rem;
    }
    &.syn-glow { box-shadow: 0 0 22px color-mix(in srgb, var(--syn-accent) var(--syn-glow-alpha, 12%), transparent); }
    /* Static atmospheric wash. This is decoration, not an interactive state. */
    &.syn-gradient-wash {
      background-image:
        radial-gradient(ellipse at 15% 10%, color-mix(in srgb, var(--syn-accent) var(--syn-wash-alpha, 15%), transparent), transparent 55%),
        radial-gradient(ellipse at 90% 80%, color-mix(in srgb, var(--syn-accent-2) var(--syn-wash-secondary-alpha, 10%), transparent), transparent 60%);
    }
    /* Gradient horizon. */
    &.syn-horizon {
      background-image:
        linear-gradient(to bottom, transparent 45%, var(--syn-bg) 100%),
        repeating-linear-gradient(to right, transparent 0 calc(3rem - 1px), color-mix(in srgb, var(--syn-accent) var(--syn-horizon-alpha, 10%), transparent) calc(3rem - 1px) 3rem),
        repeating-linear-gradient(to bottom, transparent 0 calc(3rem - 1px), color-mix(in srgb, var(--syn-accent) var(--syn-horizon-alpha, 10%), transparent) calc(3rem - 1px) 3rem),
        radial-gradient(ellipse at 70% 20%, color-mix(in srgb, var(--syn-accent) var(--syn-wash-alpha, 15%), transparent), transparent 55%);
    }
    /* Gradient atmosphere. */
    &.syn-atmosphere {
      background-image:
        radial-gradient(ellipse at 85% 10%, color-mix(in srgb, var(--syn-accent) var(--syn-wash-alpha, 15%), transparent), transparent 55%),
        radial-gradient(ellipse at 15% 90%, color-mix(in srgb, var(--syn-accent-2) var(--syn-wash-secondary-alpha, 10%), transparent), transparent 60%);
      background-color: var(--syn-bg);
    }
    &.syn-scanlines { position: relative; isolation: isolate; }
    &.syn-scanlines::after {
      content: ""; pointer-events: none; position: absolute; inset: 0; z-index: 2;
      background: repeating-linear-gradient(to bottom, transparent 0 3px, rgb(0 0 0 / var(--syn-scanline-alpha, 10%)) 3px 4px);
    }
    /* A zero-opacity grid still leaves the opaque horizon fade; remove that too. */
    @media (prefers-contrast: more) {
      &.syn-horizon { background-image: none; }
    }
    @media (forced-colors: active) {
      &.syn-scanlines::after { display: none; }
      &.syn-horizon, &.syn-atmosphere, &.syn-gradient-wash { background-image: none; }
    }
  }
}
